<?php
session_start();require_once __DIR__.'/php/conexao.php';$c=$_SESSION['farmali_carrinho']??[];if(!$c){header('Location: carrinho.php');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$total=0;foreach($c as $i)$total+=$i['preco']*$i['quantidade'];$erro='';$confirmado=isset($_GET['sucesso'])?($_SESSION['farmali_pedido_confirmado']??null):null;
if($_SERVER['REQUEST_METHOD']==='POST'&&!$confirmado){$nome=trim($_POST['nome']??'');$email=trim($_POST['email']??'');$tel=trim($_POST['telefone']??'');
 if($nome===''||!filter_var($email,FILTER_VALIDATE_EMAIL))$erro='Informe seu nome e um e-mail válido.';
 else try{
 $conexao->exec("CREATE TABLE IF NOT EXISTS PEDIDO_VENDA (COD_PEDIDO_VENDA INT AUTO_INCREMENT PRIMARY KEY,NOME_CLIENTE VARCHAR(250) NOT NULL,EMAIL_CLIENTE VARCHAR(255) NOT NULL,TELEFONE_CLIENTE VARCHAR(30),TOTAL DECIMAL(10,2) NOT NULL,STATUS ENUM('PENDENTE','CONFIRMADO','CANCELADO') DEFAULT 'PENDENTE',DATA_PEDIDO TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB");
 $conexao->exec("CREATE TABLE IF NOT EXISTS ITEM_PEDIDO_VENDA (COD_PEDIDO_VENDA_FK INT NOT NULL,COD_PRODUTO_FK INT NOT NULL,QUANTIDADE INT NOT NULL,PRECO_UNITARIO DECIMAL(10,2) NOT NULL,PRIMARY KEY(COD_PEDIDO_VENDA_FK,COD_PRODUTO_FK),FOREIGN KEY(COD_PEDIDO_VENDA_FK) REFERENCES PEDIDO_VENDA(COD_PEDIDO_VENDA),FOREIGN KEY(COD_PRODUTO_FK) REFERENCES PRODUTO(COD_PRODUTO)) ENGINE=InnoDB");
 $conexao->beginTransaction();
 foreach($c as $id=>$i){$s=$conexao->prepare("SELECT QUANTIDADE_ESTOQUE,STATUS FROM PRODUTO WHERE COD_PRODUTO=? FOR UPDATE");$s->execute([$id]);$p=$s->fetch(PDO::FETCH_ASSOC);if(!$p||$p['STATUS']!=='ATIVO'||(int)$p['QUANTIDADE_ESTOQUE']<(int)$i['quantidade'])throw new RuntimeException('Estoque insuficiente para um dos produtos. Volte ao carrinho e confira.');}
 $s=$conexao->prepare("INSERT INTO PEDIDO_VENDA(NOME_CLIENTE,EMAIL_CLIENTE,TELEFONE_CLIENTE,TOTAL) VALUES(?,?,?,?)");$s->execute([$nome,$email,$tel,$total]);$pedido=(int)$conexao->lastInsertId();
 foreach($c as $id=>$i){$s=$conexao->prepare("INSERT INTO ITEM_PEDIDO_VENDA VALUES(?,?,?,?)");$s->execute([$pedido,$id,$i['quantidade'],$i['preco']]);$s=$conexao->prepare("UPDATE PRODUTO SET QUANTIDADE_ESTOQUE=QUANTIDADE_ESTOQUE-? WHERE COD_PRODUTO=? AND QUANTIDADE_ESTOQUE>=?");$s->execute([$i['quantidade'],$id,$i['quantidade']]);if(!$s->rowCount())throw new RuntimeException('Não foi possível atualizar o estoque.');}
 $conexao->commit();unset($_SESSION['farmali_carrinho']);$_SESSION['farmali_pedido_confirmado']=['id'=>$pedido,'nome'=>$nome,'total'=>$total];header('Location: compra.php?sucesso=1');exit;
 }catch(Throwable $e){if($conexao->inTransaction())$conexao->rollBack();$erro=$e instanceof RuntimeException?$e->getMessage():'Erro ao registrar o pedido. Confira a conexão e as tabelas do banco.';}}
?>
