<main class="pagina-fluxo"><?php if($confirmado):?><section class="confirmacao-pedido"><i class="fa-solid fa-circle-check"></i><p class="sobretitulo">PEDIDO REGISTRADO</p><h1>Obrigado, <?=h($confirmado['nome'])?>!</h1><p>Pedido nº <?=$confirmado['id']?> registrado como pendente. Esta versão não processa pagamentos.</p><h2>Total: R$ <?=number_format($confirmado['total'],2,',','.')?></h2><a class="botao-primario" href="produtos.php">Voltar aos produtos</a></section><?php else:?><p class="sobretitulo">FARMAURA • FINALIZAÇÃO</p><h1>Finalizar compra</h1><p class="texto-intro">Preencha seus dados para registrar o pedido.</p><?php if($erro):?><p class="alerta-erro"><?=h($erro)?></p><?php endif;?>
<div class="carrinho-layout"><form class="form-compra" method="post"><label>Nome completo<input name="nome" required maxlength="250" value="<?=h($_POST['nome']??'')?>"></label><label>E-mail<input type="email" name="email" required maxlength="255" value="<?=h($_POST['email']??'')?>"></label><label>Telefone (opcional)<input name="telefone" maxlength="30" value="<?=h($_POST['telefone']??'')?>"></label><button class="botao-primario largura-total" type="submit">Registrar pedido</button><p class="aviso-pagamento">Projeto demonstrativo: não há cobrança nem pagamento online.</p></form><aside class="resumo-compra"><h2>Resumo</h2><?php foreach($c as $i):?><p><?=h($i['nome'])?> × <?=$i['quantidade']?></p><?php endforeach;?><div class="linha-total"><span>Total</span><strong>R$ <?=number_format($total,2,',','.')?></strong></div><a class="link-voltar" href="carrinho.php">Voltar ao carrinho</a></aside></div><?php endif;?></main>
